"""Cyclops (user art): idle, walk, throw (log leaves on frame 8), hurt, death, and the club he throws. Faces left."""
import base64
import zlib
import pygame

PAL = '1313138a48365d2c28391f21bf6f4ae69c69f9e6cff5555d891e2bf6ca9fc7cfddffffff92a1b9134c4c1e6f5033984bb4b4b4858585822c37'
ANIMS = {'idle': (140, 91, 14, ''), 'walk': (140, 91, 12, ''), 'throw': (140, 91, 17, ''), 'hurt': (140, 91, 6, ''), 'death': (140, 91, 9, ''), 'club': (62, 41, 1, 'eNqt1tkOhTAIBFBg+v/ffLvQJdUHGC+JMZocp9SaKpIurSVsqZlBP2ADy7s2FOVx00zzHo1SiNEvDKL5nUxM3cJ+SmnF0P6MnL5xSvu7so0T+gXHtT4ti0th8cwNL1TVu9/4Gj/tGHFiqi+rpEWO3v2mPuhlfV2F51hsvyQkc6ubwUC/YxbV1dWw07oPBmPow3YeDfbK7zEHRtoubJGRvgZLXu9gEWi7ooL7ahkHESz0VFP2H5jaj7VuZiyWLpWzU/O/QF9w65y3P6VpBQk=')}
VARIANTS = {}
_CACHE = {}


def _pal(variant):
  key = ('pal', variant)
  p = _CACHE.get(key)
  if p is None:
    p = [None] + [tuple(int(PAL[j + q:j + q + 2], 16) for q in (0, 2, 4)) for j in range(0, len(PAL), 6)]
    swap = VARIANTS.get(variant) if variant else None
    if swap:
      p = [None] + [tuple(swap.get(c, c)) for c in p[1:]]
    _CACHE[key] = p
  return p


def cyc_frame(name, i, scale=1.0, variant=None):
  w, h, n, data = ANIMS[name]
  i %= n
  k = (name, i, scale, variant)
  s = _CACHE.get(k)
  if s is None:
    pal = _pal(variant)
    raw = _CACHE.get((name, 'raw'))
    if raw is None:
      raw = _CACHE[(name, 'raw')] = zlib.decompress(base64.b64decode(data))
    s = pygame.Surface((w, h), pygame.SRCALPHA)
    base = i * w * h
    for p in range(w * h):
      v = raw[base + p]
      if v:
        s.set_at((p % w, p // w), pal[v] + (255,))
    if scale != 1.0:
      s = pygame.transform.scale(s, (int(w * scale), int(h * scale)))
    _CACHE[k] = s
  return s


def cyc_count(name):
  return ANIMS[name][2]
